import sys

def solve():
    m = sys.stdin.read().strip()

    if '#' not in m:
        print(0)
        return

    groups = []
    current_len = 0
    prev_was_hash = False

    for i, char in enumerate(m):
        if char == '#':
            if prev_was_hash:
                print(-1)
                return
            current_len += 1
            prev_was_hash = True
        else:
            if current_len > 0:
                groups.append(current_len)
                current_len = 0
            prev_was_hash = False

    if current_len > 0:
        groups.append(current_len)

